<script setup>
import { computed } from 'vue'
import { toolProviderIcon } from '@/features/integrations/lib/toolProviderHelpers.js'

const props = defineProps({
  type: { type: String, default: 'default' },
  size: { type: [Number, String], default: 24 },
  /** Provider icon from Integrations / tool store (url string or emoji object). */
  toolIcon: { type: [String, Object], default: null },
})

const resolvedToolIcon = computed(() => {
  if (props.toolIcon == null || props.toolIcon === '')
    return null
  return toolProviderIcon({ icon: props.toolIcon, label: '?' })
})

// Align with Dify ICON_CONTAINER_BG_COLOR_MAP (via CSS vars in theme)
const iconConfigMap = {
  start: { icon: null, bg: 'var(--node-icon-start-bg)', color: 'var(--node-icon-start-color)' },
  'start-placeholder': { icon: null, bg: 'var(--node-icon-start-bg, #2970ff)', color: '#fff' },
  end: { icon: null, bg: 'var(--node-icon-end-bg)', color: 'var(--node-icon-end-color)' },
  answer: { icon: null, bg: 'var(--node-icon-end-bg)', color: 'var(--node-icon-end-color)' },
  llm: { icon: null, bg: 'var(--node-icon-llm-bg)', color: 'var(--node-icon-llm-color)' },
  code: { icon: null, bg: 'var(--node-icon-code-bg)', color: 'var(--node-icon-code-color)' },
  'if-else': { icon: null, bg: 'var(--node-icon-branch-bg)', color: 'var(--node-icon-branch-color)' },
  iteration: { icon: null, bg: 'var(--node-icon-branch-bg)', color: 'var(--node-icon-branch-color)' },
  loop: { icon: null, bg: 'var(--node-icon-branch-bg)', color: 'var(--node-icon-branch-color)' },
  'loop-end': { icon: null, bg: 'var(--node-icon-end-bg)', color: 'var(--node-icon-end-color)' },
  'template-transform': { icon: null, bg: 'var(--node-icon-code-bg)', color: 'var(--node-icon-code-color)' },
  'variable-assigner': { icon: null, bg: 'var(--node-icon-code-bg)', color: 'var(--node-icon-code-color)' },
  'variable-aggregator': { icon: null, bg: 'var(--node-icon-code-bg)', color: 'var(--node-icon-code-color)' },
  assigner: { icon: null, bg: 'var(--node-icon-code-bg)', color: 'var(--node-icon-code-color)' },
  'human-input': { icon: null, bg: 'var(--node-icon-branch-bg)', color: 'var(--node-icon-branch-color)' },
  'document-extractor': { icon: null, bg: 'var(--node-icon-knowledge-bg)', color: 'var(--node-icon-knowledge-color)' },
  'doc-extractor': { icon: null, bg: 'var(--node-icon-knowledge-bg)', color: 'var(--node-icon-knowledge-color)' },
  'knowledge-retrieval': { icon: null, bg: 'var(--node-icon-knowledge-bg)', color: 'var(--node-icon-knowledge-color)' },
  'question-classifier': { icon: null, bg: 'var(--node-icon-knowledge-bg)', color: 'var(--node-icon-knowledge-color)' },
  'parameter-extractor': { icon: null, bg: 'var(--node-icon-code-bg)', color: 'var(--node-icon-code-color)' },
  'list-operator': { icon: null, bg: 'var(--node-icon-branch-bg)', color: 'var(--node-icon-branch-color)' },
  'http-request': { icon: null, bg: 'var(--node-icon-http-bg)', color: 'var(--node-icon-http-color)' },
  agent: { icon: null, bg: 'var(--node-icon-llm-bg)', color: 'var(--node-icon-llm-color)' },
  'agent-v2': { icon: null, bg: 'var(--node-icon-llm-bg)', color: 'var(--node-icon-llm-color)' },
  'trigger-schedule': { icon: null, bg: 'var(--node-icon-http-bg)', color: 'var(--node-icon-http-color)' },
  'trigger-webhook': { icon: null, bg: 'var(--node-icon-code-bg)', color: 'var(--node-icon-code-color)' },
  'trigger-plugin': { icon: null, bg: 'var(--node-icon-code-bg)', color: 'var(--node-icon-code-color)' },
  datasource: { icon: null, bg: '#101828', color: '#ffffff' },
  'knowledge-index': { icon: null, bg: 'var(--node-icon-end-bg)', color: 'var(--node-icon-end-color)' },
  tool: { icon: null, bg: 'var(--node-icon-code-bg)', color: 'var(--node-icon-code-color)' },
  knowledge: { icon: null, bg: 'var(--node-icon-knowledge-bg)', color: 'var(--node-icon-knowledge-color)' },
  'iteration-start': { icon: null, bg: 'var(--node-icon-code-bg)', color: 'var(--node-icon-code-color)' },
  'loop-start': { icon: null, bg: 'var(--node-icon-code-bg)', color: 'var(--node-icon-code-color)' },
}

const config = computed(() => {
  const base = iconConfigMap[props.type?.toLowerCase()] || {
    icon: null,
    bg: 'var(--node-icon-code-bg)',
    color: 'var(--node-icon-code-color)',
  }
  const tool = resolvedToolIcon.value
  if (!tool)
    return base
  if (tool.type === 'emoji' && tool.background)
    return { ...base, bg: tool.background, color: '#101828' }
  if (tool.type === 'url')
    return { ...base, bg: '#fff', color: base.color }
  return { ...base, bg: '#eff4ff', color: '#155eef' }
})
</script>

